import{_ as a,a0 as s,w as T,s as l,ao as p,I as r,x as e,a1 as o,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"Linux 有問必答：如何在wget中禁用HTTP轉發 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有問必答：如何在wget中禁用HTTP轉發 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有問必答：如何在wget中禁用HTTP轉發 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有問必答：如何在wget中禁用HTTP轉發 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141105 Linux FAQs with Answers--How to disable HTTP redirect in wget","title":"Linux 有問必答：如何在wget中禁用HTTP轉發","tag":"201411","desc":""},"relativePath":"201411/20141105 Linux FAQs with Answers--How to disable HTTP redirect in wget.md","filePath":"[post].md"}'),d={name:"201411/20141105 Linux FAQs with Answers--How to disable HTTP redirect in wget.md"};function w(m,t,u,g,L,x){const n=s("Link");return T(),l("div",null,[t[11]||(t[11]=p(`<h1 id="linux-有問必答-如何在wget中禁用http轉發" tabindex="-1">Linux 有問必答：如何在wget中禁用HTTP轉發 <a class="header-anchor" href="#linux-有問必答-如何在wget中禁用http轉發" aria-label="Permalink to “Linux 有問必答：如何在wget中禁用HTTP轉發”">​</a></h1><blockquote><p><strong>提問</strong>： 當我用wget獲取一個重定向到URL Y的URL X的時候，wget默認會自動獲取URL Y。然而我想要強制獲取不帶重定向的URL X。我該如何禁用wget重定向URL的功能。</p></blockquote><p>在HTTP標準中，重定向響應（帶3XX的HTTP響應）説明請求的URL被移到了新的位置。重定向相應接着包含了目標重定向的URL。</p><p>像常規的HTTP客户端，wget支持URL重定向（也叫URL轉發），意味着當你嘗試下載一個重定向的URL時，wget會自動跟隨URL重定向獲取重定向後的資源。如果你由於一些原因想要禁用URL重定向，並停止3XX的狀態碼，你可以使用wget的“--max-redirect=number”選項。這個選項用來指定最大（遞歸）重定向的數字，默認是20。</p><p>如果你想要禁用wget中的HTTP重定向，使用“--max-redirect=0”</p><pre><code>$ wget --max-redirect=0 http://www.aaa.com/a.html
</code></pre><hr><pre><code>--2014-10-31 23:08:58--  http://www.aaa.com/a.html
Resolving aaa.com (aaa.com)... 1.2.3.4
Connecting to aaa.com (aaa.com)|1.2.3.4|:80... connected.
HTTP request sent, awaiting response... 301 Moved Permanently
Location: http://www.bbb.com/b.html [following]
0 redirections exceeded.
</code></pre><p>如你所見，當wget遇到HTTP重定向響應時，它不會跟着重定向，並以“0 redirections exceeded”（超出0次重定向）的錯誤信息停止。它同樣會顯示一個HTTP的狀態碼（比如301）。</p><p>注意一下curl，另外一個類似的HTTP客户端，行為正好相反。默認上，curl並不會跟隨URL重定向。要強制使cutl重定向到一個URL，你要使用“-L”選項。</p><hr>`,11)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),o(n,{href:"http://ask.xmodulo.com/disable-http-redirect-wget.html"},{default:i(()=>[...t[0]||(t[0]=[e("http://ask.xmodulo.com/disable-http-redirect-wget.html",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=e("譯者：",-1)),o(n,{href:"https://github.com/geekpi"},{default:i(()=>[...t[2]||(t[2]=[e("geekpi",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:i(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),o(n,{href:"http://linux.cn/"},{default:i(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const c=a(d,[["render",w]]);export{f as __pageData,c as default};
